reactions.activationCode:
await api.executeSaveVsEffect(triggerData.hitTokens, {
    stat: 'HULL', 
    origin: reactorToken, 
    title: 'Impale',
    effects: ['immobilized', 'shredded'],
    duration: {label: "end", turns: 1},
});

const isCoreActive = reactorToken.actor.system.statuses.core_power_active;
const damageAmount = isCoreActive ? 3 : 1;

await api.executeDamageRoll(
    reactorToken, 
    [triggerData.triggeringToken], 
    damageAmount, 
    'Kinetic', 
    'Shrike Armor', 
    { ap: true }
);

await api.placeZone(reactorToken, {
    size: 1,
    range: 5,
    type: "Burst",
    difficultTerrain: { movementPenalty: 1, isFlatPenalty: true },
    title: "Caltrops",
    icon: "fas fa-road-spikes",
    centerLabel: "Caltrops",
    hooks: {
        entered: {
            function: async (template, scene, token, context) => {
                const api = game.modules.get('lancer-automations').api;
                if (await api.consumeOncePerRound(token, `caltrops_entered_${template.id}`)) {
                    await api.executeDamageRoll(
                        token, 
                        [token], 
                        "1d3", 
                        "Explosive", 
                        "Explosive Caltrops", 
                        { ap: true }
                    );
                }
            },
            asGM: false
        },
        turnEnd: {
            function: async (template, scene, token, context) => {
                const api = game.modules.get('lancer-automations').api;
                await api.executeDamageRoll(
                    token, 
                    [token], 
                    "1d3", 
                    "Explosive", 
                    "Explosive Caltrops", 
                    { ap: true }
                );
            },
            asGM: false
        }
    }
});
